<script setup lang="ts">
import StickerPicker from './StickerPicker.vue';
import StickerImage from './StickerImage.vue';
import { type Sticker } from '../../../shared/useStickers';
import { computed, ref, watch } from 'vue';
import MobileAttachment from './MobileAttachment.vue';
import { api, choosePhoto, chooseFile, uploadMedia } from '../platform';
import { type Row, formatTime } from '../../../shared/domain';
import { useChat, chatStates } from '../../../shared/useChat';
import { useRequestScope } from '../../../shared/useRequestScope';
const props = defineProps<{ user: Row | null; target?: Row | null; foreground?: boolean }>();
const emit = defineEmits<{ (event: 'join'): void; (event: 'clear-target'): void }>();
const { attachment, sticker, rooms, groups, people, active, messages, draft, error, busy, hasMore, canSend, select, detail, action, send, recall, loadPeople, create, back } = useChat(() => props.user, api, () => props.foreground !== false);
const uploading = ref(false), stickersOpen = ref(false);
function chooseSticker(item: Sticker) { if (busy.value || uploading.value || attachment.value || !canSend.value) return;sticker.value = item;stickersOpen.value = false; }
watch([() => props.user?.id, () => active.value?.id, () => canSend.value], () => { stickersOpen.value = false; }, { flush: 'sync' });
const uploadScope = useRequestScope();
watch(() => [props.user?.id, active.value?.id], () => { uploadScope.invalidate();uploading.value = false; }, { flush: 'sync' });
async function attach(kind: string) {
  const room = active.value?.id;if (!room || busy.value || uploading.value || sticker.value) return;
  const valid = uploadScope.capture();uploading.value = true;error.value = '';
  try {
    const path = kind === 'file' ? await chooseFile() : await choosePhoto(kind === 'camera');
    if (!valid()) return;
    const row = await uploadMedia(path, 'chat', room);
    if (valid()) attachment.value = row;
  } catch(e) { if (valid()) error.value = (e as Error).message; }
  finally { if (valid()) uploading.value = false; }
}
const tab = ref('chats'), screen = ref(''), form = ref<Row>({}), query = ref(''), scrollTarget = ref('');
const visible = computed(() => (tab.value === 'groups' ? groups.value : rooms.value).filter(r => r.title?.includes(query.value)));
const staff = computed(() => props.user && ['superadmin', 'admin', 'organizer'].includes(props.user.role));
async function open(kind: string) { if (props.user?.status !== 'approved') { emit('join');return; }screen.value = kind;form.value = kind === 'direct' ? { recipientId: props.target?.id || '', recipientName: props.target?.name || '', content: '' } : { title: '', description: '' };await loadPeople(); }
function choose(event: any) { const person = people.value[Number(event.detail.value)];if (person) { form.value.recipientId = person.id;form.value.recipientName = person.name; } }
async function submit() { if (await create(screen.value, form.value)) { screen.value = '';emit('clear-target'); } }
function confirmAction(value: string) { uni.showModal({ title: '确认聊天操作', content: value === 'block' ? '屏蔽后双方不能继续发送消息，你可以恢复会话。' : value === 'leave' ? '退出后不能查看记录，可从发现群聊重新加入。' : value === 'close' ? '结束后不再接收消息，已有记录保留。' : '确认恢复会话？', success: result => { if (result.confirm && active.value) action(active.value.id, value); } }); }
function canRecall(row: Row) { return !row.recalled && row.senderId === props.user?.id && Date.now() - new Date(row.createdAt).getTime() < 120000; }
watch(() => messages.value[messages.value.length - 1]?.sequence, value => { scrollTarget.value = 'chat-message-' + value; });
watch(() => props.target, target => { if (target) open('direct'); }, { immediate: true });
watch(() => props.user?.id, () => { screen.value = '';form.value = {}; });
</script>
<template>
  <view v-if="user?.status !== 'approved'" class="empty"><view class="title">聊一聊，乡情就近了</view><view class="intro">审核通过的会员可以申请私聊、自愿加入群聊。</view><button class="primary" @click="emit('join')">登录 / 查看入会状态</button></view>
  <view v-else class="mobile-chat"><view v-if="error" class="error">{{ error }}</view>
    <template v-if="screen"><button class="detail-back" :disabled="busy" @click="screen = ''; emit('clear-target')">← 返回</button><view class="form-page"><view class="form-title">{{ screen === 'direct' ? '向老乡打个招呼' : '创建老乡群聊' }}</view><template v-if="screen === 'direct'"><view class="field"><text class="field-label">选择老乡</text><picker :range="people" range-key="name" @change="choose"><view class="picker-value">{{ form.recipientName || '从自愿公开名录的会员中选择' }} ▾</view></picker></view><view class="field"><text class="field-label">说声你好，说明来意</text><textarea v-model="form.content" maxlength="500" placeholder="至少5字，对方接受后即可继续聊天"/></view><view class="safe-note">聊天不会自动公开你的手机号或微信号。</view></template><template v-else><view class="field"><text class="field-label">群聊名称</text><input v-model="form.title" maxlength="50"/></view><view class="field"><text class="field-label">群聊介绍</text><textarea v-model="form.description" maxlength="500"/></view><view class="safe-note">审核会员自愿加入，加入后可查看群聊记录。每群最多200人。</view></template><button class="primary" :disabled="busy" @click="submit">{{ screen === 'direct' ? '发送聊天申请' : '创建群聊' }}</button></view></template>
    <template v-else-if="!active"><view class="row"><view><view class="title">家里的消息</view><view class="intro">一声问候，让乡情更近。</view></view><button class="chat-new" @click="open('direct')">＋ 私聊</button></view><view class="pill-row"><text :class="['pill', { active: tab === 'chats' }]" @click="tab = 'chats'">我的会话</text><text :class="['pill', { active: tab === 'groups' }]" @click="tab = 'groups'">发现群聊</text></view><input v-model="query" class="search" placeholder="搜索老乡或群聊"/><button v-if="staff && tab === 'groups'" class="outline" @click="open('group')">创建群聊</button><view v-if="!visible.length" class="empty">{{ tab === 'groups' ? '群聊还在准备中，欢迎常来看看。' : '还没有会话，找位老乡打个招呼吧。' }}</view><view v-for="room in visible" :key="room.id" class="chat-conversation" @click="room.joined ? select(room) : action(room.id, 'join')"><view class="chat-avatar">{{ room.type === 'group' ? '群' : room.title?.slice(0,1) }}</view><view class="chat-conversation-text"><text>{{ room.title }}</text><view>{{ tab === 'groups' ? room.memberCount + '位老乡 · ' + (room.joined ? '已加入' : '点击自愿加入') : room.preview || chatStates[room.status] }}</view></view><text v-if="room.unread" class="chat-badge">{{ room.unread > 99 ? '99+' : room.unread }}</text></view><view class="safe-note">请尊重彼此，群内不发布敏感资料。</view></template>
    <view v-else class="chat-room"><view class="chat-heading"><button class="chat-return" @click="back">‹</button><view><view class="chat-name">{{ active.title }}</view><view class="chat-status">{{ chatStates[active.status] }}{{ active.type === 'group' ? ' · ' + active.memberCount + '人' : '' }}</view></view><view class="chat-actions"><button v-if="active.type === 'direct' && active.status !== 'blocked'" @click="confirmAction('block')">屏蔽</button><button v-if="active.blockedBy === user?.id" @click="confirmAction('unblock')">恢复</button><button v-if="active.type === 'group' && active.ownerId !== user?.id" @click="confirmAction('leave')">退出群聊</button><button v-if="active.type === 'group' && active.ownerId === user?.id && active.status === 'active'" @click="confirmAction('close')">结束群聊</button></view></view><view v-if="active.status === 'pending'" class="chat-request"><view>{{ active.requesterId === user?.id ? '问候已送达，等待对方接受。' : '这位老乡希望与你聊天。' }}</view><view class="button-row"><template v-if="active.requesterId !== user?.id"><button class="primary small" :disabled="busy" @click="action(active.id, 'accept')">接受聊天</button><button class="outline small" :disabled="busy" @click="action(active.id, 'reject')">暂不接受</button></template><button v-else class="text-button" :disabled="busy" @click="action(active.id, 'cancel')">取消申请</button></view></view><scroll-view scroll-y class="chat-history" :scroll-into-view="scrollTarget" scroll-with-animation><button v-if="hasMore" class="text-button" @click="detail(active.id, true)">查看更早的消息</button><view v-if="!messages.length" class="safe-note">在这里，说一声老乡好。</view><view v-for="row in messages" :id="'chat-message-' + row.sequence" :key="row.id" :class="['chat-message', { mine: row.senderId === user?.id }]"><view v-if="row.recalled" class="chat-recalled">一条消息已撤回</view><template v-else><view class="chat-avatar">{{ row.senderName?.slice(0,1) }}</view><view class="chat-message-content"><view class="chat-message-meta">{{ row.senderId === user?.id ? '我' : row.senderName }} · {{ formatTime(row.createdAt) }}</view><StickerImage v-if="row.sticker" :sticker="row.sticker"/><MobileAttachment v-if="row.attachment" :attachment="row.attachment"/><view v-if="row.content && !row.stickerOnly" class="chat-bubble">{{ row.content }}</view><text v-if="canRecall(row)" class="chat-recall" @click="recall(row)">撤回</text></view></template></view></scroll-view><StickerPicker v-if="canSend && stickersOpen" :disabled="busy || uploading || !!attachment" @choose="chooseSticker" @close="stickersOpen = false"/><view v-if="canSend" class="chat-upload-bar"><button :disabled="busy || uploading || !!attachment" @click="stickersOpen = !stickersOpen">{{ stickersOpen ? '收起表情' : '表情包' }}</button><button :disabled="busy || uploading || !!sticker" @click="attach('camera')">拍照</button><button :disabled="busy || uploading || !!sticker" @click="attach('image')">图片</button><button :disabled="busy || uploading || !!sticker" @click="attach('file')">文件</button><text v-if="uploading">上传中…</text><view v-if="attachment" class="chat-pending">{{ attachment.name }}<text @click="!busy && (attachment = null)"> 移除 ×</text></view></view><view v-if="canSend && sticker" class="sticker-pending"><StickerImage :sticker="sticker"/><text>已选：{{ sticker.label }}</text><button :disabled="busy" @click="sticker = null">移除表情</button></view><view v-if="canSend" class="chat-compose"><textarea v-model="draft" maxlength="2000" placeholder="说点什么，让乡情再近一点…"/><button class="primary" :disabled="busy || uploading || (!draft.trim() && !attachment && !sticker)" @click="send">发送</button></view><view v-else class="chat-disabled">{{ active.peerAvailable === false ? '对方暂时无法接收消息' : chatStates[active.status] }}</view></view>
  </view>
</template>
<style scoped>
.chat-new{padding:15rpx 22rpx;background:#eae0ca;color:#715d38;border-radius:20rpx;font-size:24rpx}.chat-conversation{display:flex;align-items:center;gap:22rpx;background:#fff;border-bottom:1px solid #f0ebe1;padding:28rpx 22rpx;border-radius:18rpx;margin-bottom:12rpx}.chat-avatar{width:76rpx;height:76rpx;background:#e9e3d5;color:#86714b;border-radius:24rpx;display:flex;align-items:center;justify-content:center;font-size:31rpx;flex-shrink:0}.chat-conversation-text{flex:1;min-width:0}.chat-conversation-text>text{font-weight:600;color:#243e53;font-size:29rpx}.chat-conversation-text>view{font-size:23rpx;color:#89908f;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:400rpx;margin-top:8rpx}.chat-badge{background:#c87850;color:#fff;border-radius:30rpx;padding:1rpx 10rpx;font-size:20rpx}.chat-room{background:#fff;border-radius:24rpx;overflow:hidden;border:1px solid #ebe6dc;height:calc(100vh - 190px);min-height:450px;display:flex;flex-direction:column}.chat-heading{display:flex;gap:15rpx;align-items:center;padding:22rpx 16rpx;border-bottom:1px solid #eee7db}.chat-name{font-size:29rpx;font-weight:600}.chat-status{font-size:20rpx;color:#8b9297}.chat-return{padding:0 12rpx;background:transparent;font-size:50rpx}.chat-actions{margin-left:auto}.chat-actions button{padding:8rpx;background:transparent;font-size:20rpx;color:#78858d}.chat-history{flex:1;height:0;min-height:0;background:#f8f6f1;padding:22rpx 16rpx}.chat-message{display:flex;gap:13rpx;margin-bottom:28rpx}.chat-message.mine{flex-direction:row-reverse}.chat-message .chat-avatar{width:55rpx;height:55rpx;font-size:24rpx;border-radius:16rpx}.chat-message-content{max-width:78%;min-width:0}.chat-message-meta{font-size:18rpx;color:#8a8f91;margin-bottom:8rpx}.chat-bubble{background:#fff;padding:20rpx 25rpx;border-radius:0 22rpx 22rpx;font-size:28rpx;line-height:1.8;white-space:pre-wrap;word-break:break-all;border:1px solid #e8e4db}.mine .chat-bubble{background:#243f55;color:#fff;border-color:#243f55;border-radius:22rpx 0 22rpx 22rpx}.mine .chat-message-meta{text-align:right}.chat-recalled{text-align:center;font-size:22rpx;color:#8c9498;width:100%}.chat-recall{font-size:19rpx;color:#8b979e}.chat-compose{display:flex;gap:12rpx;padding:18rpx;align-items:center;border-top:1px solid #ece7dd}.chat-compose textarea{height:90rpx;min-height:90rpx;padding:15rpx;font-size:26rpx;flex:1}.chat-compose button{font-size:24rpx;padding:17rpx 25rpx}.chat-disabled{text-align:center;padding:22rpx;font-size:23rpx;color:#8b9295}.chat-request{background:#fff4dd;padding:20rpx;font-size:24rpx;color:#876e43}.chat-request .button-row{margin-top:12rpx}
</style>
<style scoped>
.chat-history{box-sizing:border-box;width:100%}.chat-return{margin:0;flex-shrink:0;min-width:36rpx}.chat-heading>view:nth-child(2){flex:1;min-width:0}.chat-actions{flex-shrink:0}.chat-compose textarea{box-sizing:border-box;min-width:0}.chat-compose button{flex-shrink:0}
</style>

<style scoped>.chat-upload-bar{display:flex;gap:16rpx;padding:12rpx 20rpx;flex-wrap:wrap;align-items:center}.chat-upload-bar button{font-size:22rpx;color:#866f44;background:#f3eddf;padding:8rpx 18rpx}.chat-upload-bar>text,.chat-pending{font-size:22rpx;color:#876f43}.chat-pending{width:100%;word-break:break-all}.chat-compose{flex-shrink:0}</style>

<style scoped>.sticker-pending{display:flex;align-items:center;gap:10px;padding:6px 16px;flex-shrink:0;font-size:13px}.sticker-pending :deep(.sticker-picture){width:56px;height:56px;flex-shrink:0}.sticker-pending button{margin:0 0 0 auto;min-height:44px;padding:8px;font-size:13px;background:#f3eddf}</style>
